import os,glob,re,sys
sys.setrecursionlimit(10000)
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G), G['Demo pair 1 input'][0][:5])

def enclosed_fill(grid, fill):
    from collections import deque
    h,w=len(grid),len(grid[0])
    bg=grid[0][0]
    seen=[[False]*w for _ in range(h)]
    dq=deque()
    for i in range(h):
        for j in (0,w-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    for j in range(w):
        for i in (0,h-1):
            if grid[i][j]==bg and not seen[i][j]: seen[i][j]=True; dq.append((i,j))
    while dq:
        i,j=dq.popleft()
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            a,b=i+di,j+dj
            if 0<=a<h and 0<=b<w and grid[a][b]==bg and not seen[a][b]:
                seen[a][b]=True; dq.append((a,b))
    return [[fill if grid[i][j]==bg and not seen[i][j] else v for j,v in enumerate(row)] for i,row in enumerate(grid)]

